// TestBuiltinCodeSourcesAreFormatted keeps embedded Go readable: a stub or model
// answer printed to the terminal should look like the code the user would write.
func TestBuiltinCodeSourcesAreFormatted(t *testing.T) {
	set, err := drill.Builtin()
	if err != nil {
		t.Fatalf("Builtin: %v", err)
	}
	for _, d := range set.Filter("", drill.KindCode, "") {
		parts := map[string]string{
			"stub":     d.Code.Stub,
			"answer":   d.Answer,
			"preamble": d.Code.Preamble,
			"tests":    d.Code.Tests,
		}
		for name, src := range parts {
			if strings.TrimSpace(src) == "" {
				continue
			}
			file := "package lcdrill\n\n" + src + "\n"
			out, err := format.Source([]byte(file))
			if err != nil {
				t.Errorf("%s %s: does not parse: %v", d.ID, name, err)
				continue
			}
			if string(out) != file {
				t.Errorf("%s %s: not gofmt-formatted", d.ID, name)
			}
		}
	}
}

// TestBuiltinTopicsAreUsable guards against a topic with a single drill, which
// makes `-topic` a dead end after one sitting.
func TestBuiltinTopicsAreUsable(t *testing.T) {
	set, err := drill.Builtin()
	if err != nil {
		t.Fatalf("Builtin: %v", err)
	}
	for _, topic := range set.Topics() {
		if n := len(set.Filter(topic, "", "")); n < 2 {
			t.Errorf("topic %q has only %d drill(s)", topic, n)
		}
	}
}

// A code drill you cannot start is a dead 5 minutes, so every one ships a
// nudge that gets you writing without handing over the answer.
func TestBuiltinCodeDrillsHaveHints(t *testing.T) {
	set, err := drill.Builtin()
	if err != nil {
		t.Fatal(err)
	}
	for _, d := range set.All() {
		if d.Kind != drill.KindCode {
			continue
		}
		if len(d.Hints) == 0 {
			t.Errorf("%s: code drill has no hints", d.ID)
		}
		for i, h := range d.Hints {
			if strings.Contains(d.Answer, strings.TrimSuffix(h, ".")) {
				t.Errorf("%s: hint %d is copied out of the answer", d.ID, i+1)
			}
		}
	}
}

// TestEveryTopicHasCodeDrill keeps the deck from drifting back to recall-only
// topics: reciting the pattern is not the same as typing it under a clock.
func TestEveryTopicHasCodeDrill(t *testing.T) {
	// complexity drills are about analysing code, not writing it.
	exempt := map[string]bool{"complexity": true}
	set, err := drill.Builtin()
	if err != nil {
		t.Fatal(err)
	}
	for _, topic := range set.Topics() {
		if exempt[topic] {
			continue
		}
		if len(set.Filter(topic, drill.KindCode, "")) == 0 {
			t.Errorf("topic %q has no code drill", topic)
		}
	}
}
