package incl

// countDivisibleByAny returns how many integers in [1, n] are divisible by at
// least one of divisors.
func countDivisibleByAny(n int64, divisors []int64) int64 {
	if n <= 0 || len(divisors) == 0 {
		return 0
	}
	var total int64
	var walk func(i int, lcm int64, taken int)
	walk = func(i int, lcm int64, taken int) {
		// Once the running lcm passes n every extension contributes zero, so
		// the whole subtree can be dropped.
		if lcm > n {
			return
		}
		if i == len(divisors) {
			if taken == 0 {
				return
			}
			if taken%2 == 1 {
				total += n / lcm
			} else {
				total -= n / lcm
			}
			return
		}
		walk(i+1, lcm, taken)
		walk(i+1, lcmCapped(lcm, divisors[i], n), taken+1)
	}
	walk(0, 1, 0)
	return total
}

// lcmCapped returns lcm(a, b), or n+1 when that lcm would exceed n. The check
// is done by division so the multiply never overflows.
func lcmCapped(a, b, n int64) int64 {
	q := a / gcd(a, b)
	if q > n/b {
		return n + 1
	}
	return q * b
}

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}
