package incl

import (
	"math/rand"
	"testing"
)

func TestCountDivisibleByAnyExamples(t *testing.T) {
	cases := []struct {
		n    int64
		ds   []int64
		want int64
	}{
		{10, []int64{2, 3}, 7},
		{1, []int64{2}, 0},
		{100, []int64{100}, 1},
