		if got := countDivisibleByAny(c.n, c.ds); got != c.want {
			t.Fatalf("countDivisibleByAny(%d, %v) = %d, want %d", c.n, c.ds, got, c.want)
		}
	}
}

func TestCountDivisibleByAnyAgainstBruteForce(t *testing.T) {
	rng := rand.New(rand.NewSource(3))
	for trial := 0; trial < 400; trial++ {
		n := int64(1 + rng.Intn(3000))
		k := 1 + rng.Intn(8)
		seen := map[int64]bool{}
		var ds []int64
		for len(ds) < k {
			d := int64(2 + rng.Intn(29))
			if seen[d] {
				continue
			}
			seen[d] = true
			ds = append(ds, d)
		}
		var want int64
		for v := int64(1); v <= n; v++ {
			for _, d := range ds {
				if v%d == 0 {
					want++
					break
				}
			}
		}
		if got := countDivisibleByAny(n, ds); got != want {
			t.Fatalf("trial %d: n=%d ds=%v got %d, want %d", trial, n, ds, got, want)
		}
	}
}

