// No overflow guard: computes the lcm and only then compares it to n.
func countDivisibleByAny(n int64, divisors []int64) int64 {
	k := len(divisors)
	var total int64
	for mask := 1; mask < 1<<k; mask++ {
		l := int64(1)
		bits := 0
		for i := 0; i < k; i++ {
			if mask&(1<<i) == 0 {
				continue
			}
			bits++
			l = l / gcd(l, divisors[i]) * divisors[i]
		}
		if l > n {
			continue
		}
		if bits%2 == 1 {
			total += n / l
		} else {
			total -= n / l
		}
	}
	return total
}

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
