package ac

// countOccurrences returns, for each pattern, how many times it occurs in text
// counting overlaps. Patterns are lowercase a-z and may repeat.
func countOccurrences(text string, patterns []string) []int {
	// next[node][c] is the trie edge; -1 until the automaton is finished, when
	// every missing edge is redirected to where the fail link would land.
	next := [][26]int32{{}}
	for c := range next[0] {
		next[0][c] = -1
	}
	terminal := make([]int32, len(patterns))
	for i, pat := range patterns {
		cur := int32(0)
		for j := 0; j < len(pat); j++ {
			c := pat[j] - 'a'
			if next[cur][c] < 0 {
				var fresh [26]int32
				for k := range fresh {
					fresh[k] = -1
				}
				next = append(next, fresh)
				next[cur][c] = int32(len(next) - 1)
			}
			cur = next[cur][c]
		}
		terminal[i] = cur
	}

	fail := make([]int32, len(next))
	order := make([]int32, 0, len(next))
	queue := make([]int32, 0, len(next))
	for c := 0; c < 26; c++ {
		if next[0][c] < 0 {
			next[0][c] = 0
			continue
		}
		queue = append(queue, next[0][c])
	}
	for head := 0; head < len(queue); head++ {
		u := queue[head]
		order = append(order, u)
		for c := 0; c < 26; c++ {
			v := next[u][c]
			if v < 0 {
				// Missing edge: follow the fail link once, which is already
				// finished, so the redirect is a single lookup.
				next[u][c] = next[fail[u]][c]
				continue
			}
			fail[v] = next[fail[u]][c]
			queue = append(queue, v)
		}
	}

	hits := make([]int64, len(next))
	cur := int32(0)
	for i := 0; i < len(text); i++ {
		cur = next[cur][text[i]-'a']
		hits[cur]++
	}
	// A node's matches include every match of every node that fails into it,
	// so push counts down the fail tree in reverse BFS order.
	for i := len(order) - 1; i >= 0; i-- {
		u := order[i]
		hits[fail[u]] += hits[u]
	}

	out := make([]int, len(patterns))
	for i, t := range terminal {
		out[i] = int(hits[t])
	}
	return out
}
